question.answer:
def strict_reading(text):
    return int(text)


def safe_reading(text, fallback):
    try:
        return int(text)
    except ValueError:
        return fallback


def audited_reading(text):
    try:
        value = int(text)
    except ValueError:
        print("rejected")
        return None
    else:
        print("accepted")
        return value
    finally:
        print("logged")

