question.answer:
def evict(readings, key):
    # Stands in for whatever else touches this dict. Leave it alone.
    del readings[key]


def racy_lookup(readings, key):
    if key in readings:
        evict(readings, key)
        return readings[key]
    return None


def atomic_lookup(readings, key):
    try:
        return readings[key]
    except KeyError:
        return None


def convert_all(rows):
    good = []
    bad = []
    for text in rows:
        try:
            good.append(int(text))
        except ValueError:
            bad.append(text)
    return good, bad

