question.answer:
class SensorFault(Exception):
    pass


def read_channel(config, name):
    try:
        raw = config[name]
    except KeyError as exc:
        raise SensorFault(f"unknown channel {name!r}") from exc
    try:
        return int(raw)
    except ValueError as exc:
        raise SensorFault(f"channel {name!r} sent {raw!r}") from exc


def checked_read(config, name):
    try:
        return read_channel(config, name)
    except SensorFault:
        print(f"fault logged for {name!r}")
        raise


def commit(config, names):
    total = 0
    faults = []
    for name in names:
        try:
            total += read_channel(config, name)
        except SensorFault as exc:
            faults.append(str(exc))
    if faults:
        raise SensorFault(f"{len(faults)} of {len(names)} channels bad: " + "; ".join(faults))
    return total


def hierarchy():
    return (
        issubclass(KeyboardInterrupt, Exception),
        issubclass(KeyboardInterrupt, BaseException),
        issubclass(SensorFault, Exception),
    )

testcode.text:
config = {"psi": "12", "temp": "21", "flow": "n/a"}
print(read_channel(config, "psi"))
try:
    read_channel(config, "depth")
except SensorFault as exc:
    print(exc)
    print(type(exc.__cause__).__name__)
try:
    read_channel(config, "flow")
except SensorFault as exc:
    print(exc)
    print(type(exc.__cause__).__name__)

rig = {"psi": "12", "flow": "n/a"}
print(checked_read(rig, "psi"))
try:
    checked_read(rig, "flow")
except SensorFault as exc:
    print("caller saw:", exc)
    print("cause survived:", type(exc.__cause__).__name__)
print(commit(rig, ["psi"]))
try:
    commit(rig, ["psi", "flow", "depth"])
except SensorFault as exc:
    print(exc)
print(hierarchy())
